    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES — Cloudflare Radar Dark
           Inspired by: deep-space navy with electric orange accent
           =========================================== */
        :root {
            --bg-primary: #060d1f;
            --bg-secondary: #0b1630;
            --bg-card: rgba(255,255,255,0.04);
            --bg-card-border: rgba(255,255,255,0.08);
            --text-primary: #f0f4ff;
            --text-secondary: #7a90b8;
            --text-muted: #3d5278;
            --accent: #f6821f;
            --accent-2: #fbad41;
            --accent-blue: #36a3ff;
            --accent-green: #00c9a7;
            --accent-red: #ff4d6d;
            --accent-glow: rgba(246,130,31,0.25);
            --grid-line: rgba(255,255,255,0.03);

            --font-display: 'Syne', sans-serif;
            --font-body: 'Space Grotesk', sans-serif;
            --font-mono: 'Space Mono', monospace;

            /* Typography — clamp() for responsive scaling */
            --title-size: clamp(1.8rem, 5vw, 4.2rem);
            --h2-size: clamp(1.2rem, 3vw, 2.4rem);
            --h3-size: clamp(0.95rem, 2vw, 1.5rem);
            --body-size: clamp(0.7rem, 1.3vw, 1rem);
            --small-size: clamp(0.6rem, 0.9vw, 0.8rem);
            --mono-size: clamp(0.65rem, 1.1vw, 0.9rem);
            --stat-size: clamp(1.8rem, 5vw, 4rem);

            /* Spacing */
            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.6rem, 1.5vw, 1.5rem);
            --element-gap: clamp(0.3rem, 0.8vw, 0.75rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.65s;
        }

        /* ===========================================
           BASE RESET
           =========================================== */
        *, *::before, *::after {
            margin: 0; padding: 0;
            box-sizing: border-box;
        }

        body {
            background: var(--bg-primary);
            color: var(--text-primary);
            font-family: var(--font-body);
            -webkit-font-smoothing: antialiased;
        }

        /* ===========================================
           VIEWPORT BASE CSS — MANDATORY
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        .feature-list, .bullet-list {
            gap: clamp(0.4rem, 1vh, 1rem);
        }

        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.4;
        }

        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }

        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }

        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           SHARED BACKGROUND INFRASTRUCTURE
           =========================================== */
        .bg-grid {
            position: absolute; inset: 0;
            background-image:
                linear-gradient(var(--grid-line) 1px, transparent 1px),
                linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
        }

        .bg-glow {
            position: absolute;
            border-radius: 50%;
            filter: blur(80px);
            pointer-events: none;
        }

        /* ===========================================
           REVEAL ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(28px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .reveal-left {
            opacity: 0;
            transform: translateX(-40px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.88);
            transition: opacity 0.7s var(--ease-out-expo),
                        transform 0.7s var(--ease-out-expo);
        }

        .slide.visible .reveal,
        .slide.visible .reveal-left,
        .slide.visible .reveal-scale {
            opacity: 1;
            transform: none;
        }

        .reveal:nth-child(1)  { transition-delay: 0.05s; }
        .reveal:nth-child(2)  { transition-delay: 0.15s; }
        .reveal:nth-child(3)  { transition-delay: 0.25s; }
        .reveal:nth-child(4)  { transition-delay: 0.35s; }
        .reveal:nth-child(5)  { transition-delay: 0.45s; }
        .reveal:nth-child(6)  { transition-delay: 0.55s; }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0; left: 0;
            height: 2px;
            background: linear-gradient(90deg, var(--accent), var(--accent-2));
            width: 0%;
            z-index: 1000;
            transition: width 0.3s ease;
        }

        /* ===========================================
           NAVIGATION DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.75rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 900;
        }

        .nav-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--text-muted);
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
        }

        .nav-dot.active {
            background: var(--accent);
            transform: scale(1.5);
        }

        /* ===========================================
           SLIDE 1 — TITLE SLIDE
           =========================================== */
        .slide-title {
            background: var(--bg-primary);
            justify-content: center;
            align-items: flex-start;
        }

        .slide-title .bg-glow:nth-child(1) {
            width: min(60vw, 700px);
            height: min(60vw, 700px);
            background: radial-gradient(ellipse, rgba(246,130,31,0.12) 0%, transparent 70%);
            top: -20%; right: -10%;
        }

        .slide-title .bg-glow:nth-child(2) {
            width: min(40vw, 450px);
            height: min(40vw, 450px);
            background: radial-gradient(ellipse, rgba(54,163,255,0.08) 0%, transparent 70%);
            bottom: -10%; left: 5%;
        }

        .title-eyebrow {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            letter-spacing: 0.18em;
            color: var(--accent);
            text-transform: uppercase;
            margin-bottom: clamp(0.5rem, 1.5vh, 1rem);
        }

        .title-main {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.05;
            color: var(--text-primary);
            margin-bottom: clamp(0.4rem, 1.2vh, 0.8rem);
        }

        .title-main span {
            color: var(--accent);
        }

        .title-sub {
            font-size: var(--body-size);
            color: var(--text-secondary);
            max-width: min(55ch, 80vw);
            line-height: 1.6;
            margin-bottom: clamp(1rem, 3vh, 2rem);
        }

        .title-tags {
            display: flex;
            flex-wrap: wrap;
            gap: clamp(0.3rem, 0.8vw, 0.6rem);
        }

        .tag {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            padding: 0.3em 0.8em;
            border-radius: 4px;
            border: 1px solid var(--bg-card-border);
            color: var(--text-secondary);
            background: var(--bg-card);
        }

        .title-year-badge {
            position: absolute;
            right: var(--slide-padding);
            top: 50%;
            transform: translateY(-50%);
            font-family: var(--font-display);
            font-size: clamp(6rem, 18vw, 16rem);
            font-weight: 800;
            color: transparent;
            -webkit-text-stroke: 1px rgba(246,130,31,0.15);
            line-height: 1;
            pointer-events: none;
            user-select: none;
        }

        .title-bottom-bar {
            position: absolute;
            bottom: 0; left: 0; right: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent), var(--accent-2), var(--accent-blue), transparent);
        }

        /* ===========================================
           SLIDE HEADER (reused across content slides)
           =========================================== */
        .slide-header {
            margin-bottom: clamp(0.6rem, 1.5vh, 1.2rem);
        }

        .slide-num {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent);
            letter-spacing: 0.12em;
            margin-bottom: 0.3em;
        }

        .slide-title-text {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 700;
            line-height: 1.1;
            color: var(--text-primary);
        }

        .slide-title-text em {
            color: var(--accent);
            font-style: normal;
        }

        .divider {
            width: clamp(2rem, 4vw, 3rem);
            height: 2px;
            background: var(--accent);
            margin: clamp(0.4rem, 1vh, 0.8rem) 0;
        }

        /* ===========================================
           SLIDE 2 — TRAFFIC GROWTH
           =========================================== */
        .slide-traffic {
            background: var(--bg-primary);
        }

        .stat-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.6rem, 1.5vw, 1.2rem);
            margin-bottom: clamp(0.5rem, 1.5vh, 1rem);
        }

        .stat-card {
            background: var(--bg-card);
            border: 1px solid var(--bg-card-border);
            border-radius: 8px;
            padding: clamp(0.75rem, 2vw, 1.5rem);
            position: relative;
            overflow: hidden;
        }

        .stat-card::before {
            content: '';
            position: absolute;
            top: 0; left: 0;
            right: 0; height: 2px;
        }

        .stat-card.orange::before { background: linear-gradient(90deg, var(--accent), var(--accent-2)); }
        .stat-card.blue::before   { background: linear-gradient(90deg, var(--accent-blue), #7fc3ff); }
        .stat-card.green::before  { background: linear-gradient(90deg, var(--accent-green), #5ee8cd); }
        .stat-card.red::before    { background: linear-gradient(90deg, var(--accent-red), #ff8fa3); }

        .stat-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-secondary);
            letter-spacing: 0.1em;
            text-transform: uppercase;
            margin-bottom: 0.3em;
        }

        .stat-value {
            font-family: var(--font-display);
            font-size: var(--stat-size);
            font-weight: 800;
            line-height: 1;
            color: var(--text-primary);
        }

        .stat-value.orange { color: var(--accent); }
        .stat-value.blue   { color: var(--accent-blue); }
        .stat-value.green  { color: var(--accent-green); }

        .stat-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.4em;
            line-height: 1.4;
        }

        .context-row {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: clamp(0.4rem, 1vw, 0.8rem);
        }

        .context-item {
            background: var(--bg-card);
            border: 1px solid var(--bg-card-border);
            border-radius: 6px;
            padding: clamp(0.5rem, 1.2vw, 0.9rem);
        }

        .context-item .label {
            font-size: var(--small-size);
            color: var(--text-muted);
            font-family: var(--font-mono);
            text-transform: uppercase;
            letter-spacing: 0.08em;
        }

        .context-item .value {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 700;
            color: var(--text-primary);
            margin-top: 0.2em;
        }

        /* ===========================================
           SLIDE 3 — TOP 10 SERVICES
           =========================================== */
        .slide-services {
            background: var(--bg-primary);
        }

        .services-layout {
            display: grid;
            grid-template-columns: 1fr 1.1fr;
            gap: clamp(1rem, 2.5vw, 2rem);
            align-items: start;
        }

        .rank-list {
            list-style: none;
