/* ===========================================
   SLIDE PRESENTATION CONTROLLER
   =========================================== */
class SlidePresentation {
    constructor() {
        this.slides = Array.from(document.querySelectorAll('.slide'));
        this.currentSlide = 0;
        this.isScrolling = false;

        this.setupIntersectionObserver();
        this.setupKeyboardNav();
        this.setupTouchNav();
        this.setupMouseWheelNav();
        this.setupProgressBar();
        this.setupNavDots();
    }

    /* Animate slides into view via .visible class */
    setupIntersectionObserver() {
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                    const idx = this.slides.indexOf(entry.target);
                    if (idx !== -1) {
                        this.currentSlide = idx;
                        this.updateProgressBar();
                        this.updateNavDots();
                    }
                }
            });
        }, { threshold: 0.5 });

        this.slides.forEach(slide => observer.observe(slide));
    }

    /* Arrow keys, Space, Page Up/Down */
    setupKeyboardNav() {
        document.addEventListener('keydown', e => {
            if (['ArrowDown', 'ArrowRight', ' ', 'PageDown'].includes(e.key)) {
                e.preventDefault();
                this.navigateTo(this.currentSlide + 1);
            } else if (['ArrowUp', 'ArrowLeft', 'PageUp'].includes(e.key)) {
                e.preventDefault();
                this.navigateTo(this.currentSlide - 1);
            } else if (e.key === 'Home') {
                e.preventDefault();
                this.navigateTo(0);
            } else if (e.key === 'End') {
                e.preventDefault();
                this.navigateTo(this.slides.length - 1);
            }
        });
    }

    /* Touch/swipe support */
    setupTouchNav() {
        let startY = 0, startX = 0;
        document.addEventListener('touchstart', e => {
            startY = e.touches[0].clientY;
            startX = e.touches[0].clientX;
        }, { passive: true });
        document.addEventListener('touchend', e => {
            const dy = startY - e.changedTouches[0].clientY;
            const dx = startX - e.changedTouches[0].clientX;
            if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 40) {
                this.navigateTo(this.currentSlide + (dy > 0 ? 1 : -1));
            }
        });
    }

    /* Mouse wheel navigation with debounce */
    setupMouseWheelNav() {
        document.addEventListener('wheel', e => {
            if (this.isScrolling) return;
            this.isScrolling = true;
            this.navigateTo(this.currentSlide + (e.deltaY > 0 ? 1 : -1));
            setTimeout(() => { this.isScrolling = false; }, 900);
        }, { passive: true });
    }

    navigateTo(idx) {
        const target = Math.max(0, Math.min(idx, this.slides.length - 1));
        this.slides[target].scrollIntoView({ behavior: 'smooth' });
    }

    /* Progress bar at top of viewport */
    setupProgressBar() {
        this.progressBar = document.getElementById('progressBar');
        this.updateProgressBar();
    }

    updateProgressBar() {
        const pct = this.slides.length > 1
            ? (this.currentSlide / (this.slides.length - 1)) * 100
            : 100;
        if (this.progressBar) this.progressBar.style.width = pct + '%';
    }

    /* Navigation dots on right edge */
    setupNavDots() {
        const nav = document.getElementById('navDots');
        if (!nav) return;
        this.slides.forEach((_, i) => {
            const btn = document.createElement('button');
            btn.className = 'nav-dot' + (i === 0 ? ' active' : '');
            btn.setAttribute('aria-label', `Go to slide ${i + 1}`);
            btn.addEventListener('click', () => this.navigateTo(i));
            nav.appendChild(btn);
        });
    }

    updateNavDots() {
        const dots = document.querySelectorAll('.nav-dot');
        dots.forEach((d, i) => d.classList.toggle('active', i === this.currentSlide));
    }
}

new SlidePresentation();
</script>
</body>
